using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsAgingVisualReview{
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Color32[] Shot(Camera c,string path){var rt=new RenderTexture(960,720,24);c.targetTexture=rt;for(int k=0;k<3;k++)c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(960,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,960,720),0,0);t.Apply();File.WriteAllBytes(path,t.EncodeToPNG());var pixels=t.GetPixels32();RenderTexture.active=old;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);return pixels;}
 static string Pair(GameObject before,GameObject after,Camera c,string name,Vector3 pos,Vector3 target){c.transform.position=pos;c.transform.LookAt(target);after.SetActive(false);before.SetActive(true);var a=Shot(c,"Evidence/Target24Visual/"+name+"-before.png");before.SetActive(false);after.SetActive(true);var b=Shot(c,"Evidence/Target24Visual/"+name+"-after.png");long sum=0;int max=0,changed=0;for(int i=0;i<a.Length;i++){int r=Math.Abs(a[i].r-b[i].r),g=Math.Abs(a[i].g-b[i].g),bl=Math.Abs(a[i].b-b[i].b);sum+=r+g+bl;max=Math.Max(max,Math.Max(r,Math.Max(g,bl)));if(Math.Max(r,Math.Max(g,bl))>2)changed++;}double mean=(double)sum/(a.Length*3);return "{\"view\":\""+name+"\",\"meanRgbDelta\":"+mean.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"maxRgbDelta\":"+max+",\"pixelsOver2\":"+changed+"}";}
 public static void Run(){Directory.CreateDirectory("Evidence/Target24Visual");try{
  EditorSceneManager.OpenScene("Assets/RuinsTarget24Output/Room.unity");var after=GameObject.Find("ruins_1").transform.parent.gameObject;var before=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget21Output/Structures/Ruins.prefab"));Check(before!=null,"Old reference missing");var c=UnityEngine.Object.FindAnyObjectByType<Camera>();c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);var light=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).First(l=>l.type==LightType.Directional);var result=new System.Collections.Generic.List<string>();
  result.Add(Pair(before,after,c,"game",new Vector3(10,14,13),new Vector3(0,3.8f,0)));
  result.Add(Pair(before,after,c,"overview",new Vector3(15,20,19),new Vector3(0,3,0)));
  result.Add(Pair(before,after,c,"close",new Vector3(3,5.4f,-7.2f),new Vector3(0,3.55f,-4.3f)));
  result.Add(Pair(before,after,c,"stairs",new Vector3(3,6.5f,4),new Vector3(0,4.2f,0)));
  result.Add(Pair(before,after,c,"opening",new Vector3(0,6.2f,9),new Vector3(0,4.05f,4)));
  RenderSettings.ambientLight=Color.gray*.75f;light.transform.rotation=Quaternion.Euler(38,-28,0);result.Add(Pair(before,after,c,"neutral-game",new Vector3(10,14,13),new Vector3(0,3.8f,0)));result.Add(Pair(before,after,c,"neutral-close",new Vector3(3,5.4f,-7.2f),new Vector3(0,3.55f,-4.3f)));RenderSettings.ambientLight=Color.gray*.3f;light.transform.rotation=Quaternion.Euler(50,200,0);result.Add(Pair(before,after,c,"opposite",new Vector3(-15,20,-19),new Vector3(0,3,0)));
  light.transform.rotation=Quaternion.Euler(65,20,0);var gray=new Material(Shader.Find("Universal Render Pipeline/Lit"));gray.SetColor("_BaseColor",new Color(.55f,.55f,.55f));gray.SetFloat("_Smoothness",.15f);foreach(var root in new[]{before,after})foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name!="TerrainCaps"))r.sharedMaterial=gray;
  result.Add(Pair(before,after,c,"mono",new Vector3(3,5.4f,-7.2f),new Vector3(0,3.55f,-4.3f)));
  result.Add(Pair(before,after,c,"mono-stairs",new Vector3(3,6.5f,4),new Vector3(0,4.2f,0)));
  File.WriteAllText("Evidence/Target24Visual/result.json","{\"sameSceneAndLights\":true,\"threeWarmupRenders\":true,\"pairs\":["+string.Join(",",result)+"]}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText("Evidence/Target24Visual/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
